function freshState(id,g=game){return{id,core:0,surgeUntil:0,ult:null,internal:0,lastX:g?.player?.x||0,lastY:g?.player?.y||0,lastAng:null,carves:[],clean:0,paths:[],locks:new Map(),dough:[],hot:[],seams:[],buoy:null,caught:new Set(),cells:0,hives:[],bees:[],stakes:[],triPulse:0,glassPhase:'hot',coolUntil:0,crystals:[],altitude:0,falconReady:true,reagents:[],formula:null,lastFormula:null,grandNext:false,ports:[],digSites:[],relics:[],bellSeq:[],bellNeed:0,beacons:[],parryUntil:0,riposteCharges:0,touche:0,opponent:null,frames:[],recording:false,replay:[],attackCount:0,lastBand:null,lastCoreText:'READY',tick:0};}
function state(g=game){if(!g||!IDS.includes(g.characterId))return null;g.vsxExpansion16 ||= freshState(g.characterId,g);if(g.vsxExpansion16.id!==g.characterId)g.vsxExpansion16=freshState(g.characterId,g);return g.vsxExpansion16}
function resetState(g=game){if(g)g.vsxExpansion16=IDS.includes(g.characterId)?freshState(g.characterId,g):null;return g?.vsxExpansion16||null}
function gainCore(g,n,label){const s=state(g);if(!s||s.internal)return;if(label)s.lastCoreText=label;s.core=clamp16(s.core+n);if(s.core>=100)startSurge(g,s)}
function announce(title,body,color){try{VSX.announce?.(title,body,color)}catch{}}
function damageLine(g,a,b,width,damage,source,color='#8edfff',status=null){g.beams?.push?.({x1:a.x,y1:a.y,x2:b.x,y2:b.y,life:.16,color,width:Math.max(2,width*.28)});let hits=0;const cx=(a.x+b.x)/2,cy=(a.y+b.y)/2,r=Math.hypot(b.x-a.x,b.y-a.y)/2+width+45;for(const e of g.grid?.queryCircle?.(cx,cy,r)||[]){if(!alive(e))continue;if(segDist(e.x,e.y,a.x,a.y,b.x,b.y)<=e.size+width){g.damageEnemy(e,damage,{source,canCrit:true,knockback:30,fromX:a.x,fromY:a.y,silent:true});if(status)e.applyStatus?.(status.type,status.duration,status.strength,source);hits++}}return hits}
function burst(g,x,y,r,dmg,color,source,knock=55){g.explosion?.(x,y,r,dmg,color,knock,source,false)}
function strongest(g,r=800){const a=(g.grid?.queryCircle?.(g.player.x,g.player.y,r)||[]).filter(alive);a.sort((x,y)=>(y.hp||0)-(x.hp||0));return a[0]||null}
function spawnProj(g,w,s,target,extra={}){if(!target)return null;const d=dirTo(g.player,target),q=new Projectile({x:g.player.x,y:g.player.y,vx:d.x*(extra.speed||s.speed||560),vy:d.y*(extra.speed||s.speed||560),radius:extra.radius||s.size||5,damage:extra.damage||s.damage,life:extra.life||1.5,color:extra.color||'#dff6ff',weapon:w,pierce:extra.pierce??s.pierce??0,knockback:extra.knockback??s.knockback??20,behavior:extra.behavior,homingStrength:extra.homingStrength||0,target:extra.target||null,explosionRadius:extra.explosionRadius||0,projectileStyle:extra.projectileStyle||null,maxLife:extra.maxLife});Object.assign(q,extra.props||{});g.projectiles.push(q);return q}
function addRoute(s,a,b,life=3,color='#84e7ff'){s.paths.push({a:{...a},b:{...b},life,max:life,color});if(s.paths.length>12)s.paths.shift()}
function pointInTri(p,a,b,c){const s1=(p.x-a.x)*(b.y-a.y)-(p.y-a.y)*(b.x-a.x),s2=(p.x-b.x)*(c.y-b.y)-(p.y-b.y)*(c.x-b.x),s3=(p.x-c.x)*(a.y-c.y)-(p.y-c.y)*(a.x-c.x);return (s1>=0&&s2>=0&&s3>=0)||(s1<=0&&s2<=0&&s3<=0)}
function mixFormula(a,b){const x=[a,b].sort().join('+');return{'red+red':'VOLATILE','blue+blue':'FROST TONIC','green+green':'VENOM','blue+red':'STEAM','blue+green':'NUMBING MIST','green+red':'CORROSIVE'}[x]||null}
function formulaColor(f){return{'VOLATILE':'#ff785d','FROST TONIC':'#8fe9ff','VENOM':'#8fec72','STEAM':'#e7f4ff','NUMBING MIST':'#a9d9d7','CORROSIVE':'#c7ef5f'}[f]||'#c5efef'}
function formulaCast(g,s,f,grand=false){const t=cluster(g,g.player.x,g.player.y,760),x=t?.x||g.player.x,y=t?.y||g.player.y,r=(grand?150:82)*g.player.areaMultiplier,d=(grand?48:23)*g.player.damageMultiplier,source=coreSource('apothecary');burst(g,x,y,r,d,formulaColor(f),source,45);for(const e of g.grid?.queryCircle?.(x,y,r)||[]){if(!alive(e))continue;if(f==='FROST TONIC'||f==='NUMBING MIST')e.applyStatus?.('slow',grand?4:2.5,grand ? .55 : .35,source);if(f==='VENOM'||f==='CORROSIVE')e.applyStatus?.('poison',grand?5:3,grand?5:3,source);if(f==='VOLATILE'||f==='STEAM')e.applyStatus?.('burn',grand?4:2.5,grand?5:3,source);if(f==='CORROSIVE')e.applyStatus?.('vulnerable',grand?4:2,.18,source)}s.lastFormula=f;s.lastCoreText=(grand?'GRAND ':'')+f;announce(grand?'GRAND FORMULA':'FORMULA',f,formulaColor(f))}

